    const lyrics = [
      'This is the malt',
      'that lay in the house that Jack built.',
    ];
    expect(House.verse(2)).toEqual(lyrics);
  });

  test('verse three - the rat that ate', () => {
    const lyrics = [
      'This is the rat',
      'that ate the malt',
      'that lay in the house that Jack built.',
    ];
    expect(House.verse(3)).toEqual(lyrics);
  });

