    const lyrics = [
      'This is the cat',
      'that killed the rat',
      'that ate the malt',
      'that lay in the house that Jack built.',
    ];
    expect(House.verse(4)).toEqual(lyrics);
  });

  test('verse five - the dog that worried', () => {
    const lyrics = [
      'This is the dog',
      'that worried the cat',
      'that killed the rat',
      'that ate the malt',
      'that lay in the house that Jack built.',
    ];
    expect(House.verse(5)).toEqual(lyrics);
  });

